mapper.select:
SELECT count(*)::bigint AS sampled_rows,COALESCE(sum(size),0)::bigint AS sampled_bytes,
  min(expires_at) AS oldest_expiry,count(*)>=#{limit} AS saturated FROM (
    SELECT size,expires_at FROM public.nw_chat_session_attachments
    WHERE tenant_id=CAST(#{tenant} AS bigint) AND expires_at<=clock_timestamp() AND body_format IS NOT NULL
    ORDER BY expires_at,id LIMIT #{limit}
  ) expired
